mapper.select:
SELECT COUNT(1)
FROM (
    SELECT DEPT_CD
    FROM TB_DEPARTMENT
    WHERE NVL(USE_YN, 'Y') = 'Y'
    START WITH PRNT_DEPT_CD = #{deptCd}
    CONNECT BY PRIOR DEPT_CD = PRNT_DEPT_CD
)
WHERE DEPT_CD = #{candidateParentDeptCd}

mapper.update:
UPDATE TB_DEPARTMENT
SET USE_YN = 'N',
    LAST_MDFCN_DT = SYSDATE,
    LAST_MDFR_ID = #{lastMdfrId}
WHERE DEPT_CD = #{deptCd}
  AND NVL(USE_YN, 'Y') = 'Y'

